}

button,
input,
select,
textarea {
    font-size: 100%;
    margin: 0;
    vertical-align: baseline;
    *vertical-align: middle;
    outline: 0;
}

button,
input {
    line-height: normal;
    *overflow: visible;
}

table button,
table input {
    *overflow: auto;
}

button,
input[type="button"],
input[type="reset"],
input[type="submit"] {
    cursor: pointer;
    -webkit-appearance: button;
}

input[type="checkbox"],
input[type="radio"] {
    box-sizing: border-box;
}

input[type="search"] {
    -webkit-appearance: textfield;
    -moz-box-sizing: content-box;
    -webkit-box-sizing: content-box;
    box-sizing: content-box;
}

input[type="search"]::-webkit-search-decoration {
    -webkit-appearance: none;
}

button::-moz-focus-inner,
input::-moz-focus-inner {
    border: 0;
    padding: 0;
}

textarea {
    overflow: auto;
    vertical-align: top;
    resize: vertical;
}

input:valid,
textarea:valid {}

input:invalid,
textarea:invalid {
    background-color: #f0dddd;
}

p {
    margin: 5px 0 15px 0;
}

h1,
h2,
h3,
h4,
h5,
h6 {
    margin: 0;
}

a:link,
a:visited {
    color: #007fd0;
    text-decoration: none;
}

a:hover,
a:active {
    color: #ff7500;
    text-decoration: underline;
}

.wrapper {
    width: 950px; 
    padding: 0 10px;
    margin: 0 auto;
    box-sizing: border-box;
}

.wrapper:after {
    content: "";
    display: table;
    clear: both;
}

@media only screen and (min-width:1140px) {
    .wrapper {
        width: 88%;
        max-width: 1250px;
        padding: 0;
        margin: 0 auto;
    }
}

.logo {
    display: block;
    text-decoration: none;
}

.logo__icon>svg {
    height: 40px;
    width: 50px;
    display: inline-block;
    vertical-align: middle;
}

.logo__icon>svg * {
    transition: fill 0.25s ease;
}

.logo__text {
 font-family:"Asap",sans-serif;
 font-style:italic;
 color:#fff;
 text-indent:5px
}

.logo:hover {
    text-decoration: none
}

.logo--light .logo__icon>svg * {
    fill: #fff
}

.logo--light:hover .logo__icon>svg * {
    fill: #ccc
}

.logo--primary .logo__icon>svg * {
    fill: #007fd0
}

.logo--primary:hover .logo__icon>svg * {
    fill: #ff7500
}

.header {
    background: #393d3f;
    font: 16px/26px "Open Sans", sans-serif;
    display: flex;
    flex-direction: row;
    height: 75px
}

.js .header {
    position: fixed;
    z-index: 10;
    right: 0;
    left: 0;
    top: 0
}

.header__title {
    height: 100%;
    margin: 0;
    float: left
}

.header__title .logo {
    align-items: center;
    display: flex;
    height: 100%
}

.header .wrapper {
    position: relative
}

.header .menu-button,
.header .menu-close-button {
    display: none
}

.header__checkbox {
    display: none
}




.main-menu {
    height: 100%
}

.main-menu__links {
    height: 100%;
    list-style: none;
    margin: 0;
    padding: 0;
    font-size: 0;
    display: flex;
}

.main-menu__links__gap {
    flex-grow: 2
}

.main-menu__links__item {
    flex-grow: 1
}

.main-menu__links__item__link {
    display: block;
    margin: 0;
    font-size: 18px;
    height: 100%;
    font-weight: 300;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.25s ease;
}

.main-menu__links__item__link:link,
.main-menu__links__item__link:visited {
    color: #fff;
    text-decoration: none;
}

.main-menu__links__item__link:hover,
.main-menu__links__item__link:active {
    background: rgba(85, 85, 85, 0.6);
}

.main-menu__links__item--search {
    flex-grow: 0;
    padding: 0 0 0 20px;
    position: relative;
    justify-content: center;
    align-items: center;
}

.js .main-menu__links__item--search {
    display: flex;
}

.main-menu__links__item--search__icon .icon svg {
    width: 20px;
    height: 20px;
    vertical-align: middle;
    margin-top: -2px;
    margin-left: 0;
    margin-right: 0;
}

.main-menu__links__item--search__icon .icon svg * {
    fill: #999 !important;
}

.main-menu__links__item--search__icon:hover,
.main-menu__links__item--search__icon:active {
    cursor: pointer;
}

.main-menu__links__item--search__icon:hover .icon svg *,
.main-menu__links__item--search__icon:active .icon svg * {
    fill: #ccc !important;
}

.main-menu__links__item--active {
    background: #007fd0;
    color: #fff;	
}

.main-menu__links__item--active .main-menu__links__item__link {
    color: inherit;
}

.main-menu__links__item--active .main-menu__links__item__link:hover,
.main-menu__links__item--active .main-menu__links__item__link:active {
    background: #007fd0;
}

.site-search {
    background: #393d3f;
    text-align: right;
    padding: 15px 0 14px 0;
    position: absolute;
    top: 0;
    right: 0;
    width: 77%;
    will-change: transform;
    transition: transform 0.25s linear, opacity 0.25s linear;
    transform: translateY(-100%);
    opacity: 0;
}

.site-search input[type="text"].site-search__field {
    font: 16px "Open Sans", sans-serif;
    border: 1px solid #fff;
    font-size: 0.9em;
    outline: 0;
    border-radius: 4px;
    box-sizing: border-box;
    margin: 1px 5px 1px 0;
    width: 250px;
    padding: 7px 7px 8px 7px;
}

.site-search button {
    font: 0.9em/26px "Open Sans", sans-serif
}

.site-search__button--cancel.site-button {
    margin-right: 0;
    display: inline-block;
}

#show-site-search:checked~.site-search {
    opacity: 1;
    transform: translateY(0%);
}



.header .site-button,
.header a.site-button {
    color: #fff;
    background: #007fd0;
    border: 1px solid #007fd0;
    padding: 4px 10px;
    margin: 5px;
    font-size: 0.9em;
    text-decoration: none;
    display: inline-block;
    line-height: 26px;
    border-radius: 4px;
}

.header .site-button:link,
.header .site-button:visited,
.header a.site-button:link,
.header a.-sitebutton:visited {
    color: #fff;
}

.header .site-button:hover,
.header .site-button:active,
.header a.site-button:hover,
.header a.site-button:active {
    background: #ff7500;
    border-color: #ff7500;
    text-decoration: none;
    cursor: pointer;
}

.header .site-button .icon svg,
.header a.site-button .icon svg {
    width: 16px;
    height: 16px;
    vertical-align: middle;
    margin-top: -2px;
    margin-left: 0;
    margin-right: 6px;
}

.header .site-button .icon svg *,
.header a.site-button .icon svg * {
    fill: #fff !important;
}

.header .site-button.site-button--dark,
.header a.site-button.site-button--dark {
    background: #393D3F;
    border-color: #666;
}

.header .site-button.site-button--dark:hover,
.header a.site-button.site-button--dark:hover {
    border-color: #999;
}

.header .site-button:hover,
.header .site-button:active,
.header a.site-button:hover,
.header a.site-button:active {
    outline: none;
}

.headroom {
    will-change: transform;
    transition: transform 200ms linear;
}

.headroom--pinned {
    transform: translateY(0%);
}

.headroom--unpinned {
    transform: translateY(-100%);
}

.headroom--unpinned.headroom--disabled {
    transform: translateY(0%);
}

.footer {
    background: #393D3F;
    font: 16px/26px "Open Sans", sans-serif;
}

.footer .wrapper {
    padding: 20px 0;
    display: flex;
    justify-content: space-between;
    padding: 0;
    flex-direction: row;
}

.footer__nav {
    flex-grow: 1;
}

.footer__nav__links {
    list-style: none;
    margin: 0;
    padding: 0;
}

.footer__nav__links__item {
    font-size: 0.8em;
    padding: 0;
    display: inline-block;
}

@media only screen and (min-width:1140px) {
    .footer__nav__links__item {
        font-size: 0.8em;
    }
}

.footer__nav__links__item__link {
    display: block;
    transition: background 0.25s ease, color 0.25s ease;
    padding: 14px 6px;
}

@media only screen and (min-width:1140px) {
    .footer__nav__links__item__link {
        padding: 18px 12px;
    }
}

.footer__nav__links__item__link:link,
.footer__nav__links__item__link:visited,
.footer__nav__links__item__link:hover,
.footer__nav__links__item__link:active {
    color: #ccc;
    text-decoration: none;
}

.footer__nav__links__item__link:hover,
.footer__nav__links__item__link:active {
    color: #fff;
    background: rgba(85, 85, 85, 0.6);
}

.footer__nav__links__item__link .icon svg {
    width: 16px;
    height: 16px;
    vertical-align: middle;
    margin-top: -2px;
    margin-left: auto;
    margin-right: auto;
    margin-right: 2px;
}

.footer__nav__links__item__link .icon svg * {
    fill: #999 !important;
}

.footer__nav--internal {
    text-transform: uppercase;
}

.footer__nav--social {
    text-align: right;
}

.copyright {
